return [
  {
    json: {
      created: true,
      campaign_id: campaign.campaign_id,
      campaign_name: campaign.name,
      ruleset_version: campaign.ruleset_version,
      summary: Object.assign({}, planned.summary, { in_scope_written: created.length }),
      rejected: planned.rejected,
      next: `Launch it with ppwr-campaign-launch and campaign_id ${campaign.campaign_id}.`,
    },
  },
];
